<?php declare(strict_types=1);use FastWebsite\Core\View;$path=is_string($unit['hero_path'])?str_replace('\\','/',$unit['hero_path']):'';$image=$path!==''&&preg_match('#^(?:https?:)?//#i',$path)!==1?$baseUrl.ltrim(preg_replace('#^public/#','',$path)??$path,'/'):null;$name=static fn(array$m):string=>trim(implode(' ',array_filter([$m['honorific_title'],$m['first_name'],$m['middle_name'],$m['last_name']])));?>
<section class="admin-page-heading"><div><p class="eyebrow"><?=View::escape($unit['type_name'])?></p><h1><?=View::escape($unit['name'])?></h1><span class="status-badge status-<?=View::escape($unit['status'])?>"><?=View::escape(ucfirst(str_replace('_',' ',$unit['status'])))?></span></div><div class="heading-actions"><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research">All research</a><?php if($canEdit):?><a class="button <?=$canQuickPublish?'button-secondary':'button-primary'?>" href="<?=View::escape($baseUrl)?>admin/research/<?=(int)$unit['id']?>/edit">Edit</a><?php endif;?><?php if($canQuickPublish):?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/<?=(int)$unit['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><input type="hidden" name="action" value="publish_now"><button class="button button-primary publish-button" type="submit">Publish now</button></form><?php endif;?></div></section>
<?php if(is_string($success)&&$success!==''):?><div class="success-alert" role="status"><?=View::escape($success)?></div><?php endif;?><?php if($needsOverviewToPublish):?><div class="form-alert publish-guidance"><strong>Ready to publish?</strong> Add an overview while editing, then use “Save and publish”.</div><?php endif;?>
<div class="record-grid"><div class="record-main"><?php if($image):?><section class="admin-panel record-hero"><img src="<?=View::escape($image)?>" alt="<?=View::escape($unit['hero_alt_text']?:$unit['name'])?>"></section><?php endif;?><?php foreach(['Overview'=>'overview','Research focus'=>'research_focus','Facilities and capabilities'=>'capabilities','Student opportunities'=>'student_opportunities','Industry and community services'=>'industry_services']as$heading=>$field):?><?php if(is_string($unit[$field])&&trim($unit[$field])!==''):?><section class="admin-panel record-section"><h2><?=$heading?></h2><div class="prose"><?=nl2br(View::escape($unit[$field]))?></div></section><?php endif;?><?php endforeach;?>
<section class="admin-panel" id="members"><div class="panel-heading"><h2>Research team</h2></div><?php if($members===[]):?><p class="admin-empty compact">No current members assigned.</p><?php else:?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Staff member</th><th>Role</th><th></th></tr></thead><tbody><?php foreach($members as$member):?><tr><th><?=View::escape($name($member))?></th><td><?=View::escape($member['role_title']?:ucwords(str_replace('_',' ',$member['membership_role'])))?></td><td><?php if($canManageMembers):?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/<?=(int)$unit['id']?>/members/<?=(int)$member['id']?>/remove"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="button button-secondary button-compact" type="submit">Remove</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($canManageMembers&&$staffOptions!==[]):?><form class="content-form member-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/<?=(int)$unit['id']?>/members"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><div class="form-grid"><div class="form-field span-2"><label for="staff_id">Staff member</label><select id="staff_id" name="staff_id" required><?php foreach($staffOptions as$staff):?><option value="<?=(int)$staff['id']?>"><?=View::escape($name($staff))?></option><?php endforeach;?></select></div><div class="form-field"><label for="membership_role">Role</label><select id="membership_role" name="membership_role"><?php foreach(['lead','deputy_lead','researcher','technician','graduate_researcher','student_researcher','affiliate','external_collaborator','other']as$role):?><option value="<?=$role?>"><?=ucwords(str_replace('_',' ',$role))?></option><?php endforeach;?></select></div><div class="form-field"><label for="role_title">Custom title</label><input id="role_title" name="role_title" maxlength="150"></div><div class="form-field"><label for="start_date">Start date</label><input id="start_date" name="start_date" type="date"></div><div class="form-field"><label for="member_order">Display order</label><input id="member_order" name="display_order" type="number" min="0" max="65535" value="0"></div></div><button class="button button-primary" type="submit">Add member</button></form><?php endif;?></section></div>
<aside class="record-sidebar"><section class="admin-panel"><h2>Research details</h2><dl class="detail-list"><div><dt>Type</dt><dd><?=View::escape($unit['type_name'])?></dd></div><div><dt>Department</dt><dd><?=View::escape($unit['department_name']??'Faculty-wide')?></dd></div><div><dt>Public URL</dt><dd>/research/<?=View::escape($unit['slug'])?></dd></div><?php if($unit['email']):?><div><dt>Email</dt><dd><?=View::escape($unit['email'])?></dd></div><?php endif;?></dl></section><?php if($actions!==[]):?><section class="admin-panel"><h2>Workflow action</h2><form class="workflow-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/<?=(int)$unit['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><div class="form-field"><label for="research-comment">Comment</label><textarea id="research-comment" name="comment" rows="3"></textarea></div><div class="workflow-actions"><?php foreach($actions as$action):?><button class="button <?=$action['action']==='published'?'button-primary':'button-secondary'?>" type="submit" name="action" value="<?=View::escape($action['action'])?>"><?=View::escape($action['label'])?></button><?php endforeach;?></div></form></section><?php endif;?><section class="admin-panel"><h2>Workflow history</h2><?php if($history===[]):?><p class="admin-empty compact">No actions yet.</p><?php else:?><ol class="history-list"><?php foreach($history as$entry):?><li><strong><?=View::escape(ucfirst(str_replace('_',' ',$entry['action'])))?></strong><span><?=View::escape($entry['actor_name']??'Former user')?></span></li><?php endforeach;?></ol><?php endif;?></section></aside></div>
